import random

GROUP = "number_theory"
SKILL = "counting"

def count_ways(target, min_digit, max_digit):
    ways = [0] * (target + 1)
    ways[0] = 1

    for digit in range(min_digit, max_digit + 1):
        for i in range(target, digit - 1, -1):
            ways[i] += ways[i - digit]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_digit = rng.randint(1, 5)
    max_digit = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)
    check_max_count = 0
    for digit in range(min_digit, max_digit + 1):
        if digit <= target_sum:
            check_max_count += count_ways(target_sum - digit, min_digit, digit - 1)

    answer = count_ways(target_sum, min_digit, max_digit)
    assert answer == check_max_count, f"answer={answer} check={check_max_count}"

    problem = (
        f"Consider a number with digits ranging from {min_digit} to {max_digit} (inclusive). "
        f"How many distinct sets of digits can be formed such that the maximum digit does not exceed the target sum {target_sum} and all digits sum to exactly {target_sum}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "combinatorics"
SKILL = "counting"

def count_ways(target, min_day, max_day):
    ways = [0] * (target + 1)
    ways[0] = 1

    for day in range(min_day, max_day + 1):
        if day > target:
            continue
        for i in range(target, day - 1, -1):
            ways[i] += ways[i - day]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_day = rng.randint(1, 5)
    max_day = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)
    check_max_count = 0
    for day in range(min_day, max_day + 1):
        if day <= target_sum:
            check_max_count += count_ways(target_sum - day, min_day, day - 1)

    answer = count_ways(target_sum, min_day, max_day)
    assert answer == check_max_count, f"answer={answer} check={check_max_count}"

    problem = (
        f"In a month where days can range from {min_day} to {max_day} (inclusive), "
        f"how many distinct sets of days can be formed such that the maximum day does not exceed the target sum {target_sum} and all days sum to exactly {target_sum}? State only the integer."
    )
    return problem, str(answer)
